import { Group, Mesh, PlaneGeometry, MeshBasicNodeMaterial, MeshStandardNodeMaterial, Color, Box3, DirectionalLight, AmbientLight } from 'three/webgpu';
import { uv, vec2, vec3, mix, fract, sin, dot, add, mul, sub } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const root = new Group();
  root.userData.handlers = {};
  const timelines = [];

  // --- Lights ---
  // Key: 45° left, 30° down
  const keyLight = new DirectionalLight(0xffffff, 1.2);
  keyLight.position.set(2, 2, 3);
  root.add(keyLight);

  // Rim: opposite, warm accent hue
  const rimLight = new DirectionalLight(0xff2a38, 0.8);
  rimLight.position.set(-2, -1, -2);
  root.add(rimLight);

  // Ambient fill
  const ambientLight = new AmbientLight(0x404060, 0.6);
  root.add(ambientLight);

  // --- Backdrop (full frame coverage) ---
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  const st = uv();
  const color1 = vec3(0.043, 0.043, 0.063); // #0b0b10
  const color2 = vec3(0.075, 0.075, 0.102); // #13131a
  const gradient = mix(color1, color2, st.y);
  const grain = fract(sin(dot(mul(st, 100.0), vec2(12.9898, 78.233))) * 43758.5453123);
  const grainAmount = 0.015;
  const finalColor = add(gradient, mul(sub(mul(grain, 2.0), 1.0), grainAmount));
  backdropMat.colorNode = finalColor;
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -1.5;
  backdrop.position.y = 0; // center to fill frame y=-3 to y=3
  root.add(backdrop);

  // --- Hero line: "TIME, MACHINED." ---
  // Create full text from font atlas
  const heroAtlas = ctx.fontAtlas.createText("TIME, MACHINED.", {
    fontSize: 124,
    color: '#e8ecf2',
    align: 'left',
    letterSpacingPx: -1.24
  });

  // Sort meshes by x position
  const allGlyphs = [];
  heroAtlas.traverse((child) => {
    if (child.isMesh) {
      allGlyphs.push(child);
    }
  });

  // Sort left to right
  allGlyphs.sort((a, b) => a.position.x - b.position.x);

  // Detect word boundary (space gap > 0.03 scene units at current scale)
  let gapIndex = 0;
  for (let i = 0; i < allGlyphs.length - 1; i++) {
    const diff = allGlyphs[i + 1].position.x - allGlyphs[i].position.x;
    if (diff > 0.03) {
      gapIndex = i + 1;
      break;
    }
  }

  // Group glyphs by word
  const wordGroups = [];
  const words = [
    allGlyphs.slice(0, gapIndex),
    allGlyphs.slice(gapIndex)
  ];

  const zOffsets = [0.12, -0.12]; // front to back per word

  words.forEach((wordGlyphs, idx) => {
    const wordGroup = new Group();
    wordGlyphs.forEach((glyph) => {
      // Store original local position relative to atlas group
      const pos = glyph.position.clone();
      // Remove from atlas group
      heroAtlas.remove(glyph);
      // Add to word group (preserve local position)
      wordGroup.add(glyph);
      glyph.position.copy(pos);
    });
    wordGroup.position.z = zOffsets[idx];
    wordGroups.push(wordGroup);
  });

  // Build hero line group
  const heroLineGroup = new Group();
  wordGroups.forEach((wg) => heroLineGroup.add(wg));

  // Scale down to em height 0.62 scene units (original fontSize 124 → scale factor 0.005)
  const scaleFactor = 0.005;
  heroLineGroup.scale.setScalar(scaleFactor);

  // After scaling, compute bounding box to center horizontally
  const tempGroup = heroLineGroup.clone();
  tempGroup.scale.setScalar(1); // undo clone scaling? Actually clone preserves scale, so we need to recompute box manually?
  // Better: compute box on children directly after scale? Since scale is applied to group, the world positions of children are scaled. We can compute the box in scaled space by multiplying child positions by scaleFactor.
  // But simpler: temporary unscale children for box calculation.
  // Actually we can compute bounding box of heroLineGroup (with scale) by temporarily setting scale to 1 and multiplying positions.
  // We'll store the original scaled positions and compute box.
  const dummyBox = new Box3();
  wordGroups.forEach((wg) => {
    wg.children.forEach((mesh) => {
      const worldPos = new Vector3();
      mesh.getWorldPosition(worldPos); // This will include group scale? Actually getWorldPosition considers ancestors' scale.
      // But we haven't added to scene yet, so worldPos is relative to heroLineGroup's local space with scale applied. That's fine.
      dummyBox.expandByPoint(worldPos);
    });
  });
  const centerX = (dummyBox.min.x + dummyBox.max.x) / 2;
  // Position group so that text is centered at world x=0
  heroLineGroup.position.x = -centerX;
  heroLineGroup.position.y = 0.4;

  // Apply standard material with lighting response to all glyphs
  heroLineGroup.traverse((child) => {
    if (child.isMesh) {
      const origMat = child.material;
      const newMat = new MeshStandardNodeMaterial();
      newMat.color = origMat.color || new Color('#e8ecf2');
      newMat.roughness = 0.5;
      newMat.metalness = 0.3;
      newMat.emissive = new Color('#000000');
      newMat.emissiveIntensity = 0;
      child.material = newMat;
      child.material.transparent = true;
      child.material.opacity = 0;
      child.material.needsUpdate = true;
    }
  });

  root.add(heroLineGroup);

  // --- Cinematic primitive: kinetic-text ---
  const kineticResult = ctx.primitives['kinetic-text'](heroLineGroup, {
    staggerMs: 60,
    riseUnits: 0.35
  });
  timelines.push(kineticResult.timeline);

  // --- Weighted settle after final glyph ---
  const glyphCount = allGlyphs.length;
  const settleDelay = (glyphCount - 1) * 0.06 + 0.7;
  const settleTL = gsap.timeline({ delay: settleDelay });
  settleTL
    .set(heroLineGroup.scale, { x: scaleFactor * 1.04, y: scaleFactor * 1.04, z: scaleFactor * 1.04 })
    .to(heroLineGroup.scale, {
      x: scaleFactor,
      y: scaleFactor,
      z: scaleFactor,
      duration: 0.9,
      ease: 'cubic-bezier(0.165,0.84,0.44,1)'
    });
  timelines.push(settleTL);

  // --- Accent underline (anchored left) ---
  // Compute text width in scene units (after scaling)
  const textWidth = dummyBox.max.x - dummyBox.min.x;
  const underlineWidth = 2.6; // fixed spec width
  const underlineGeo = new PlaneGeometry(underlineWidth, 0.045);
  underlineGeo.translate(underlineWidth / 2, 0, 0); // move center to left edge + half width
  const underlineMat = new MeshStandardNodeMaterial();
  underlineMat.color = new Color('#ff2a38');
  underlineMat.emissive = new Color('#ff2a38');
  underlineMat.emissiveIntensity = 1.2;
  underlineMat.roughness = 0.4;
  underlineMat.metalness = 0.6;
  const underline = new Mesh(underlineGeo, underlineMat);
  underline.position.y = -0.05;
  underline.position.x = dummyBox.min.x; // align left edge of underline with text left edge
  underline.scale.x = 0;
  heroLineGroup.add(underline);

  const underlineDelay = settleDelay + 0.12;
  const underlineTL = gsap.to(underline.scale, {
    x: 1,
    duration: 0.5,
    delay: underlineDelay,
    ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
  });
  timelines.push(underlineTL);

  // --- Subhead ---
  const subheadText = ctx.fontAtlas.createText("Every calibre begins as a solid billet.", {
    fontSize: 40,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: 0.8
  });
  subheadText.scale.setScalar(0.005);
  subheadText.position.y = -0.65;
  // Initial state for fade-up
  subheadText.traverse((child) => {
    if (child.isMesh) {
      child.material.transparent = true;
      child.material.opacity = 0;
      child.material.needsUpdate = true;
    }
  });
  root.add(subheadText);

  const subheadTL = gsap.to(subheadText.position, {
    y: -0.65,
    duration: 0.5,
    ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
    delay: 0.5,
    startAt: { y: -0.45 }
  });
  timelines.push(subheadTL);

  subheadText.traverse((child) => {
    if (child.isMesh) {
      const matTL = gsap.to(child.material, {
        opacity: 1,
        duration: 0.5,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        delay: 0.5
      });
      timelines.push(matTL);
    }
  });

  // --- Caption ---
  const captionText = ctx.fontAtlas.createText("NOVA ATELIER / CALIBRE PROGRAM", {
    fontSize: 18,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: 2.16
  });
  captionText.scale.setScalar(0.005);
  captionText.position.y = 1.15;
  root.add(captionText);

  // --- Cleanup ---
  root.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    kineticResult.cleanup();
    // Dispose geometries and materials (optional)
  };

  return root;
}
